"""Clients finden den Server im LAN per UDP-Broadcast, ohne dass jemand eine IP abtippen muss."""

import json
import logging
import socket
import threading

log = logging.getLogger(__name__)

MAGIC = b"HEBOCON?"


def serve(udp_port: int, http_port: int, server_id: str, stop: threading.Event) -> None:
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        sock.bind(("", udp_port))
    except OSError as exc:
        log.warning("Automatische Suche aus (UDP %d belegt: %s); Clients brauchen die IP.", udp_port, exc)
        return
    sock.settimeout(1.0)
    answer = json.dumps({"app": "hebocon", "port": http_port, "id": server_id}).encode()
    with sock:
        while not stop.is_set():
            try:
                data, addr = sock.recvfrom(64)
            except TimeoutError:
                continue
            except OSError:
                # Windows meldet ICMP-Fehler früherer Antworten hier; der Socket bleibt nutzbar.
                continue
            if data == MAGIC:
                sock.sendto(answer, addr)


def lan_addresses() -> list[str]:
    """IPv4-Adressen dieses Rechners, die Hauptadresse zuerst."""
    found: list[str] = []
    try:
        # Verbindet nur logisch, sendet nichts; liefert die Adresse der Standardroute, auch ohne Internet.
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.connect(("10.255.255.255", 1))
            found.append(s.getsockname()[0])
    except OSError:
        pass
    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            found.append(info[4][0])
    except OSError:
        pass
    return [ip for ip in dict.fromkeys(found) if not ip.startswith(("127.", "0."))]
